class SponsorImportService{public function __construct(private readonly GovUkSponsorRegisterClient $client){}public function import(?callable $advance=null):ImportStats{$stats=new ImportStats();$start=microtime(true);$log=ImportLog::create(['source_url'=>config('services.govuk.sponsor_register_url'),'status'=>'running','started_at'=>now()]);try{$csvUrl=$this->client->latestCsvUrl();$csv=$this->client->downloadCsv($csvUrl);$tmp=tempnam(sys_get_temp_dir(),'sponsors');file_put_contents($tmp,$csv);DB::transaction(function () use($tmp,$stats,$advance){$file=new SplFileObject($tmp);$file->setFlags(SplFileObject::READ_CSV|SplFileObject::SKIP_EMPTY);$headers=[];$now=Carbon::now();$batch=[];foreach($file as $row){if($row===[null]||$row===false){continue;}if($headers===[]){$headers=array_map(fn($h)=>strtolower(trim((string)$h)),$row);continue;}$stats->downloaded++;$data=@array_combine($headers,array_pad($row,count($headers),''));if(!$data||empty($data['organisation name'])){$stats->skipped++;continue;}$routes=array_values(array_filter(array_map('trim',explode(',',(string)($data['route']??$data['routes']??'')))));$batch[]=['company_name'=>trim($data['organisation name']),'slug'=>Sponsor::makeSlug($data['organisation name'],$data['postcode']??null),'town'=>$data['town/city']??$data['town']??null,'county'=>$data['county']??null,'postcode'=>$data['postcode']??null,'licence_number'=>$data['licence number']??null,'organisation_type'=>$data['type & rating']??$data['organisation type']??null,'routes'=>json_encode($routes),'rating'=>$data['rating']??$this->rating($data),'status'=>$data['status']??'Licensed','imported_at'=>$now,'created_at'=>$now,'updated_at'=>$now];if(count($batch)>=1000){$stats->imported+=count($batch);Sponsor::upsert($batch,['company_name','postcode','licence_number'],['slug','town','county','organisation_type','routes','rating','status','imported_at','updated_at']);$batch=[];if ($advance !== null) { $advance(); }}}if($batch){$stats->imported+=count($batch);Sponsor::upsert($batch,['company_name','postcode','licence_number'],['slug','town','county','organisation_type','routes','rating','status','imported_at','updated_at']);}});@unlink($tmp);Cache::flush();$stats->duration=microtime(true)-$start;$log->update(['csv_url'=>$csvUrl,'status'=>'success','downloaded_rows'=>$stats->downloaded,'imported_rows'=>$stats->imported,'updated_rows'=>$stats->updated,'skipped_rows'=>$stats->skipped,'failed_rows'=>$stats->failed,'duration_seconds'=>$stats->duration,'finished_at'=>now()]);return $stats;}catch(Throwable $e){$stats->duration=microtime(true)-$start;$stats->failed++;$log->update(['status'=>'failed','failed_rows'=>$stats->failed,'duration_seconds'=>$stats->duration,'message'=>$e->getMessage(),'finished_at'=>now()]);Log::error('Sponsor import failed',['exception'=>$e]);throw $e;}}private function rating(array $data):?string{$text=(string)($data['type & rating']??'');return str_contains($text,'A rating')?'A rating':(str_contains($text,'B rating')?'B rating':null);}}
